// --- CONFIGURAÇÃO MESTRE: ISAAC LUIS ---
const body = $input.item.json.body || $input.item.json;
const idAtendimento = body.id_atendimento || body.atendimento_id || body.session_id || body.sessionId || '';

// 1. LIMPEZA DE DADOS
const telefoneRaw = body.telefone_cliente || body.telefone_contato || body.telefone || '';
const telefoneLimpo = telefoneRaw.toString().replace(/\D/g, ''); 
const nomePaciente = body.nome_cliente || body.nome_contato || 'Paciente';

// --- DEFINIÇÃO DE FUSO HORÁRIO ---
const TIMEZONE = 'America/Sao_Paulo';

// 2. REGRAS DE HORÁRIO ISAAC LUIS 
const FECHADO = null;

const REGRAS_SEMANA = {
    1: { manha: {ini: {h:10,m:30}, fim: {h:11,m:30}}, tarde: {ini: {h:15,m:0}, fim: {h:16,m:0}} }, // Segunda
    2: { manha: null, tarde: {ini: {h:15,m:0}, fim: {h:16,m:0}} },    // Terça (Só tarde)
    3: { manha: {ini: {h:8,m:0}, fim: {h:9,m:0}}, tarde: {ini: {h:15,m:0}, fim: {h:16,m:0}} },     // Quarta
    4: { manha: null, tarde: {ini: {h:15,m:0}, fim: {h:16,m:0}} },    // Quinta (Só tarde)
    5: FECHADO, // Sexta
    6: FECHADO,    // Sábado (Só manhã)
    7: FECHADO  // Domingo
};

// 3. CONFIGURAÇÃO DA AGENDA ÚNICA
const CONFIG_UNIDADE = {
    id_agenda: 'c14337ebeb07f51cef2e2b768b5aec462424b5481674d830262076618f849d89@group.calendar.google.com',
    nome_unidade: 'ISAAC LUIS',
    nome_empresa: 'ISAAC LUIS',
    timezone: TIMEZONE,
    regras_horario: REGRAS_SEMANA,
    feriados: ['21/04'],      // <-- NOVO: FORMATO DD/MM
    duracao_servico: 30,
    capacidade_simultanea: 2,
    trava_agendamento: 3,
    trava_remarcacao: 2
};

// 4. TRATAMENTO DE DATAS (CORREÇÃO DE FUSO) 
let dataFinal = "";
let horaFinal = "";
let dataAntigaBusca = null;

// Data Principal (Agendamento/Novo)
const dataRaw = body.data_iso || body.data_inicio || body.data_agendada;
if (dataRaw) {
    let dt = DateTime.fromISO(dataRaw, { zone: TIMEZONE });
    if (!dt.isValid) dt = DateTime.fromFormat(dataRaw, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });

    if (dt.isValid) {
        dataFinal = dt.toFormat('dd/MM/yyyy');
        horaFinal = dt.toFormat('HH:mm');
    }
}

// Data Antiga (Para Remarcação)
if (body.data_antiga) {
     let dtAntiga = DateTime.fromISO(body.data_antiga, { zone: TIMEZONE });
     if (!dtAntiga.isValid) dtAntiga = DateTime.fromFormat(body.data_antiga, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
     if (dtAntiga.isValid) dataAntigaBusca = dtAntiga.toISO();
}

// 5. SAÍDA FINAL
const config_agenda = CONFIG_UNIDADE;

return {
  json: {
    ...body,
    data_agendada: dataFinal,
    horario_agendado: horaFinal,
    data_antiga_iso: dataAntigaBusca,
    telefone_limpo: telefoneLimpo,
    nome_paciente: nomePaciente,
    config_agenda: config_agenda,
    acao_fluxo: body.action,
    id_atendimento:    idAtendimento,
    helena_company_id: 'fc93514a-bd6a-4701-bd77-d9cad0cfc4ff',
  }
};

// --- LÓGICA SCANNER ISAAC LUIS (CORREÇÃO DE DATA SOLICITADA) ---
const itemConfig = $('Configuracao Unidades').first(); 
const dadosConfig = itemConfig ? itemConfig.json : {};
const configAgenda = dadosConfig.config_agenda; 
const TIMEZONE = configAgenda.timezone || 'America/Sao_Paulo';

// REGRAS APLICADAS
const DURACAO_MINUTOS = configAgenda.duracao_servico || 30; 
const CAPACIDADE_MAXIMA = configAgenda.capacidade_simultanea || 2; 
const eventosOcupados = $input.all().map(i => i.json);
const feriados = configAgenda.feriados || []; // <-- NOVO

const agora = DateTime.now().setZone(TIMEZONE);

// REGRA DE SEGURANÇA BASE: Não agendar no passado (pelo menos 2 horas de frente)
const inicioSeguroDefault = agora.plus({ hours: 2 });
let inicioSeguro = inicioSeguroDefault;

// 🟢 FIX: Capturar a data solicitada pelo cliente do Nó 1
if (dadosConfig.data_agendada) {
    const horaSolicitada = dadosConfig.horario_agendado && dadosConfig.horario_agendado !== "00:00" 
                           ? dadosConfig.horario_agendado 
                           : "00:00"; // Se não mandou hora exata, varre o dia todo

    const dtSolicitada = DateTime.fromFormat(`${dadosConfig.data_agendada} ${horaSolicitada}`, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });

    if (dtSolicitada.isValid) {
        // Se a data solicitada for no futuro, a busca começa a partir dela.
        // Se o cliente pediu uma data no passado (ex: ontem), a trava inicioSeguroDefault entra em ação.
        if (dtSolicitada > inicioSeguroDefault) {
            inicioSeguro = dtSolicitada;
        }
    }
}

// --- FUNÇÃO AUXILIAR: CHECAR SE É FERIADO ---
function ehFeriado(data) {
    return feriados.includes(data.toFormat('dd/MM'));
}

// Checa se a data solicitada é feriado usando o inicioSeguro já calculado
const dataSolicitadaEhFeriado = ehFeriado(inicioSeguro.startOf('day'));

function checarCapacidade(slotData) {
    let ocupados = 0;
    const inicioSlot = slotData;
    const fimSlot = slotData.plus({ minutes: DURACAO_MINUTOS });

    for (const evento of eventosOcupados) {
        if (!evento || !evento.start) continue;
        if (evento.status === 'cancelled') continue;

        let iniEvt = evento.start.dateTime 
            ? DateTime.fromISO(evento.start.dateTime).setZone(TIMEZONE) 
            : DateTime.fromISO(evento.start.date).setZone(TIMEZONE).startOf('day');

        let fimEvt = evento.end.dateTime 
            ? DateTime.fromISO(evento.end.dateTime).setZone(TIMEZONE) 
            : DateTime.fromISO(evento.end.date).setZone(TIMEZONE).endOf('day');

        if (inicioSlot < fimEvt && fimSlot > iniEvt) {
            ocupados++;
        }
    }
    return ocupados < CAPACIDADE_MAXIMA; 
}

// --- SCANNER DE SUGESTÕES ---
let sugestoes = [];
// 🟢 FIX: O cursor agora começa do dia solicitado pelo cliente (ou de hoje, se for nulo/passado)
let cursorDia = inicioSeguro.startOf('day');
let diasVerificados = 0;

// Busca nos próximos 7 dias a partir da data solicitada
while (sugestoes.length < 3 && diasVerificados < 7) {
    // --- PULAR FERIADOS ---
    if (ehFeriado(cursorDia)) {
        cursorDia = cursorDia.plus({ days: 1 });
        diasVerificados++;
        continue;
    }

    const regraDia = configAgenda.regras_horario[cursorDia.weekday];

    if (regraDia) {
        const blocos = [regraDia.manha, regraDia.tarde];
        for (const turno of blocos) {
            if (turno && (turno.ini.h > 0 || turno.fim.h > 0 || turno.ini.m > 0)) {
                let loopTime = cursorDia.set({ hour: turno.ini.h, minute: turno.ini.m });
                const fimTurno = cursorDia.set({ hour: turno.fim.h, minute: turno.fim.m });

                while (loopTime.plus({minutes: DURACAO_MINUTOS}) <= fimTurno) {
                    // Verifica se o horário é futuro (a partir do momento/hora solicitada) e se tem vaga
                    if (loopTime >= inicioSeguro && checarCapacidade(loopTime)) {
                        sugestoes.push(loopTime);
                    }

                    if (sugestoes.length >= 3) break;

                    loopTime = loopTime.plus({ minutes: DURACAO_MINUTOS });
                }
            }
            if (sugestoes.length >= 3) break;
        }
    }
    cursorDia = cursorDia.plus({ days: 1 });
    diasVerificados++;
}

// FORMATAÇÃO DA RESPOSTA
let linhas = sugestoes.map(s => `🗓️ *${s.setLocale('pt-BR').toFormat("dd/MM (ccc)")}* às *${s.toFormat("HH:mm")}*`).join('\n');

let respostaFinal = "";
if (dataSolicitadaEhFeriado && sugestoes.length > 0) {
    const dataFormatada = inicioSeguro.startOf('day').toFormat('dd/MM');
    respostaFinal = `O dia *${dataFormatada}* é feriado e a clínica não atende. 🗓️\n\nMas já separei algumas opções disponíveis:\n\n${linhas}\n\nQual desses fica melhor para você?`;
} else if (sugestoes.length > 0) {
    respostaFinal = `Para a Clínica ${configAgenda.nome_unidade}, encontrei estes horários disponíveis mais próximos:\n\n${linhas}\n\nQual desses fica melhor para você?`;
} else {
    respostaFinal = `Poxa, não encontrei horários disponíveis para os dias próximos à data solicitada.`;
}

return { json: { resultado: respostaFinal, sugestoes_iso: sugestoes.map(s => s.toISO()) } };

